//* Config plugin: build the native (C++) code with a recent CMake
// Windows only: the CMake 3.22 that React Native asks for by default ships ninja 1.10,
// which fails on object paths over 260 characters ("Filename longer than 260 characters"),
// even with long paths enabled in Windows. Ninja handles them from 1.12 on, bundled with
// the recent CMake packages of the Android SDK (downloaded by Gradle on first build).
// android/ is generated by `expo prebuild`: this plugin re-applies the setting every time.
const { withProjectBuildGradle } = require('expo/config-plugins')

const MARK = '// withCmakeVersion'

module.exports = function withCmakeVersion(config, version = '3.31.6') {
  return withProjectBuildGradle(config, (mod) => {
    const gradle = mod.modResults.contents
    if (gradle.includes(MARK)) return mod

    // The version must be set while each module is configured, so this block goes BEFORE
    // React Native's root plugin, which configures :app early ("It is too late to set version").
    const block = `${MARK}: every module with C++ (app, libraries) uses CMake ${version}
subprojects { project ->
  ['com.android.application', 'com.android.library'].each { id ->
    project.plugins.withId(id) { project.android.externalNativeBuild.cmake.version = '${version}' }
  }
}

`
    const at = gradle.indexOf('apply plugin:')
    mod.modResults.contents = at === -1 ? gradle + '\n' + block : gradle.slice(0, at) + block + gradle.slice(at)
    return mod
  })
}
